  static final ArchRule businessCodeHasNoTechnicalDetails =
      noClasses().that().resideInAnyPackage(
              "com.example.payment.domain..", "com.example.payment.application..")
          .should().dependOnClassesThat(resideInAnyPackage(TECHNICAL));

  @ArchTest
  static final ArchRule infrastructureDoesNotDependOnApp =
      noClasses().that().resideInAPackage("com.example.payment.infrastructure..")
          .should().dependOnClassesThat().resideInAPackage("com.example.payment.app..");
